using Emulation;

namespace GameBoy.CPU;

/// <summary>
/// This class houses the executional logic of the CPU, which uses the state to determine what to do next
/// and to store values for and generated by those executions.
/// </summary>
public sealed partial class LR35902 : ICPU
{
    //--------------------------------------------------------------------------------------------------//
    //                                          ATTRIBUTES                                              //
    //--------------------------------------------------------------------------------------------------//
    // 1 DMG Machine Cycle equates to 4 clock cycles (or T-cycles) on the CPU.
    private const uint MachineCycle = 4;
    
    // Interrupt codes for the CPU
    private const ushort InterruptFlagAddress   = 0xFF0F;
    private const ushort InterruptEnableAddress = 0xFFFF;
    private const byte   InterruptVBlank        = 0x01;
    private const byte   InterruptStat          = 0x02;
    private const byte   InterruptTimer         = 0x04;
    private const byte   InterruptSerial        = 0x08;
    private const byte   InterruptJoypad        = 0x10;
    
    private readonly LR35902State _state = new();
    private          Bus?         _bus;
    private          bool         _interruptEnabledPendingStateSnapshot;
    
    public ICPUState State => _state;
    
    //--------------------------------------------------------------------------------------------------//
    //                                          FUNCTIONS                                               //
    //--------------------------------------------------------------------------------------------------//
    /// <summary> Attach a BUS, usually loaded from a ROM. </summary>
    public void AttachBus(Bus bus) => _bus = bus;

    /// <summary> Reset logic for the CPU. </summary>
    public void Reset()
    {
        _state.Reset();
        _bus = null;
    }

    //--------------------------------------------------------------------------------------------------//
    //                                            OPCODES                                               //
    //--------------------------------------------------------------------------------------------------//
    /// <summary> Step the next instruction and executes the opcode found at that instruction. </summary>
    public void StepInstruction()
    {
        if (_bus is null) return;   // nothing loaded so nothing to do
        
        // Interrupt wake/service is checked before normal opcode execution.
        // HALT wakes when any enabled interrupt is pending. Interrupt servicing itself only occurs when IME is enabled.
        if (HandleInterrupts()) return;
        
        // Don't step if state is halted or stopped.
        if (_state.Halted || _state.Stopped) return;
        
        // EI on previous instruction is applied only after the current instruction completes.
        // Create a snapshot of the current InterruptEnabledPending state.
        _interruptEnabledPendingStateSnapshot = _state.InterruptEnabledPending;

        // Read the Next opcode from the BUS (loaded from the cart)
        byte opcode = _bus.ReadByte(_state.PC);
        
        _state.StepPC();                     // Step the Program Counter then execute the opcode
        _state.AddClockCycles(MachineCycle); // fetch uses a machine cycle.

        switch (opcode)
        {
            //----------    MISC    ----------//
            //--- NOP
            case 0x00:
                CompleteInstruction(); return;  
            
            //--- PREFIX CB
            case 0xCB:
                ExecuteCBOpcode(ReadNextByte()); return;

            //---------- CTRL ----------//
            //--- STOP
            case 0x10:
            {
                _state.Stop();  // Enter stopped state until external wake event.
                
                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - STOP is a 1-byte instruction in this simplified model.
                CompleteInstruction();
                return;
            }

            //--- HALT
            case 0x76:
            {
                bool interruptPending = GetPendingInterrupts() != 0;
                _state.Halt(_state.InterruptMasterEnabled, interruptPending);
                
                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - STOP is a 1-byte instruction in this simplified model.
                CompleteInstruction();
                return;
            }
            
            //--- DI (Disable Interrupts)
            case 0xF3:
            {
                _state.DisableInterrupts();   // DI clears IME immediately and cancels any pending EI enable.

                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }

            //--- EI (Enable Interrupts)
            case 0xFB:
            {
                _state.ScheduleInterruptEnable(); // EI does not enable IME immediately on LR35902.

                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }

            //----------    LD16    ----------//
            //--- LD rr,d16
            case 0x01: case 0x11: case 0x21: case 0x31:
            {
                // Read the next 16-bits from operand; advances PC past both bytes.
                ushort val = ReadNextWord();

                // bits 5-4 of these opcodes encode which 16-bit register pair to load:
                // 00=BC, 01=DE, 10=HL, 11=SP
                switch ((opcode >> 4) & 0x03)
                {
                    case 0x00: _state.BC = val; break;
                    case 0x01: _state.DE = val; break;
                    case 0x02: _state.HL = val; break;
                    case 0x03: _state.SP = val; break;
                }
                
                // Timing:  (12 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - LD rr,d16:    8 cycles.
                _state.AddClockCycles(MachineCycle * 2);
                CompleteInstruction();
                return;
            }
            
            //------------------------    ALU16   ------------------------//
            case 0x03: case 0x13: case 0x23: case 0x33:     //--- INC rr
                INC_rr(opcode); return;
            
            case 0x0B: case 0x1B: case 0x2B: case 0x3B:     //--- DEC rr
                DEC_rr(opcode); return;
            
            case 0x09: case 0x19: case 0x29: case 0x39:     //--- ADD HL,rr
                ADD_HL_rr(opcode); return;
            
            case 0xE8:                                      //--- ADD SP,e8
                ADD_SP_e8(opcode); return;
            
            case 0xF8:                                      //--- LD HL,SP+e8
                LD_HL_SPe8(opcode); return;
            
            //--- LD SP,HL
            case 0xF9:
            {
                _state.SP = _state.HL;   // Copy the 16-bit value in HL into SP.

                // Timing:  (8 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - LD SP,HL:     4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }
            

            //----------    LD8    ----------//
            //--- LD r,d8
            case 0x06: case 0x0E: case 0x16: case 0x1E: 
            case 0x26: case 0x2E: case 0x36: case 0x3E:
            {
                // Read the next 8-bits from bus; advances PC past that byte.
                byte val = ReadNextByte();
                
                // Bits 5-3 encode the destination register index:
                // 0=B, 1=C, 2=D, 3=E, 4=H, 5=L, 6=(HL), 7=A.
                int dest = (opcode >> 3) & 0x07;
                
                WriteReg8(dest, val);
                
                
                // Timing:  (8/12 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - LD r,d8:      4 cycles.
                //  - LD (HL),d8:   8 cycles.
                _state.AddClockCycles((dest == 6) ? MachineCycle * 2 : MachineCycle);
                CompleteInstruction();
                return;
            }
            
            //--- LD r,r' (0x40..0x7F, except 0x76 which is HALT, 64 opcodes total)
            case >= 0x40 and <= 0x7F when opcode != 0x76:
            {
                // Encoding:
                int dst = (opcode >> 3) & 0x07; // bits 5-3 = destination register (B,C,D,E,H,L,(HL),A)
                int src = opcode & 0x07;        // bits 2-0 = source register      (B,C,D,E,H,L,(HL),A)
                
                // Read from source register/memory and write to destination register/memory.
                WriteReg8(dst, ReadReg8(src));
                
                // Timing:  (8/12 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - r->r form:    0 cycles.
                //  - HL forms:     4 cycles.
                if (src == 6 || dst == 6) _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }
            
            //------------------------    ALU8    ------------------------//
            case 0x04: case 0x0C: case 0x14: case 0x1C:     //- INC r/(HL)
            case 0x24: case 0x2C: case 0x34: case 0x3C:
                ExecuteIncRHl(opcode); return;
            case 0x05: case 0x0D: case 0x15: case 0x1D:     //- DEC r/(HL)
            case 0x25: case 0x2D: case 0x35: case 0x3D:
                ExecuteDecRHl(opcode); return;
            case 0x80: case 0x81: case 0x82: case 0x83:     //- ADD A,r
            case 0x84: case 0x85: case 0x86: case 0x87:
                ExecuteAddAr(opcode); return;
            case 0x88: case 0x89: case 0x8A: case 0x8B:     //- ADC A,r
            case 0x8C: case 0x8D: case 0x8E: case 0x8F:
                ExecuteAdcAr(opcode); return;
            case 0xC6:                                      //- ADD A,d8
            case 0xCE:                                      //- ADC A,d8
                ExecuteAddAdcAd8(opcode); return;
            case 0x90: case 0x91: case 0x92: case 0x93:     //- SUB A,r
            case 0x94: case 0x95: case 0x96: case 0x97:
                ExecuteSubAr(opcode); return;
            case 0x98: case 0x99: case 0x9A: case 0x9B:     //- SBC A,r
            case 0x9C: case 0x9D: case 0x9E: case 0x9F:
                ExecuteSbcAr(opcode); return;
            case 0xD6:                                      //- SBC A,d8
            case 0xDE:                                      //- SBC A,d8
                ExecuteSubSbcAd8(opcode); return;
            case 0xA0: case 0xA1: case 0xA2: case 0xA3:     //- AND A,r
            case 0xA4: case 0xA5: case 0xA6: case 0xA7:
                ExecuteAndAr(opcode); return;
            case 0xE6:                                      //- AND A,d8
                ExecuteAndAd8(opcode); return;
            case 0xA8: case 0xA9: case 0xAA: case 0xAB:     //- XOR A,r
            case 0xAC: case 0xAD: case 0xAE: case 0xAF:
                ExecuteXorAr(opcode); return;
            case 0xEE:                                      //- XOR A,d8
                ExecuteXorAd8(opcode); return;
            case 0xB0: case 0xB1: case 0xB2: case 0xB3:     //- OR A,r
            case 0xB4: case 0xB5: case 0xB6: case 0xB7:
                ExecuteOrAr(opcode); return;
            case 0xF6:                                      //- OR A,d8
                ExecuteOrAd8(opcode); return;
            case 0xB8: case 0xB9: case 0xBA: case 0xBB:     //- CP A,r
            case 0xBC: case 0xBD: case 0xBE: case 0xBF:
                ExecuteCpAr(opcode); return;
            case 0xFE:                                      //- CP A,d8
                ExecuteCpAd8(opcode); return;
            case 0x27:                                      //- DAA
                ExecuteDaa(opcode); return;
            case 0x2F:                                      //- CPL
                ExecuteCpl(opcode); return;
            case 0x37:                                      //- SCF
                ExecuteScf(opcode); return;
            case 0x3F:                                      //- CCF
                ExecuteCcf(opcode); return;
            //------------------------------------------------------------//

            //----------    ROTATE    ----------//
            //--- RLCA (Rotate Left Circular Accumulator)
            case 0x07:
            {
                bool carry = (_state.A & 0x80) != 0;                         // Capture bit 7, this becomes carry & new bit 0.
                _state.A   = (byte)((_state.A << 1) | (carry ? 1 : 0));      // Rotate A left circular.
                
                // RLCA flags on LR35902: Z=0, N=0, H=0, C=old bit7.
                SetFlagsZNHC(z: false, n: false, h: false, c: carry);
                
                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }
            //--- RRCA (Rotate Right Circular Accumulator)
            case 0x0F:
            {
                bool carry = (_state.A & 0x01) != 0;                          // Capture bit 0, this becomes carry & new bit 7.
                _state.A   = (byte)((_state.A >> 1) | (carry ? 0x80 : 0x00)); // Rotate A right circular.
                
                // RRCA flags on LR35902: Z=0, N=0, H=0, C=old bit7.
                SetFlagsZNHC(z: false, n: false, h: false, c: carry);

                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }

            //--- RLA (Rotate Left through Accumulator)
            case 0x17:
            {
                bool oldCarry = _state.FlagC;                            // RLA Rotates left through carry:
                bool carryOut = (_state.A & 0x80) != 0;                  // old carry -> bit 0, old bit 7 -> new carry.
                
                _state.A = (byte)((_state.A << 1) | (oldCarry ? 1 : 0));
                
                // RLA flags on LR35902: Z=0, N=0, H=0, C=old bit7.
                SetFlagsZNHC(z: false, n: false, h: false, c: carryOut);
                
                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }
            //--- RRA (Rotate Right through Accumulator)
            case 0x1F:
            {
                bool oldCarry = _state.FlagC;                            // RLA Rotates right through carry:
                bool carryOut = (_state.A & 0x01) != 0;                  // old carry -> bit 0, old bit 7 -> new carry.
                
                _state.A = (byte)((_state.A >> 1) | (oldCarry ? 0x80 : 0x00));
                
                // RLA flags on LR35902: Z=0, N=0, H=0, C=old bit7.
                SetFlagsZNHC(z: false, n: false, h: false, c: carryOut);
                
                // Timing:  (4 total cycles)
                //  - opcode fetch: 4 cycles.
                CompleteInstruction();
                return;
            }
            
            //----------    FLOW    ----------//
            //--- JR r8
            case 0x18:
            {
                sbyte offset = unchecked((sbyte)ReadNextByte());
                _state.PC = (ushort)(_state.PC + offset);
                
                _state.AddClockCycles(MachineCycle * 2); // total 12
                CompleteInstruction();
                return;
            }
            
            //--- JR N',e8
            case 0x20:/*JR NZ,e8*/ case 0x28:/*JR Z,e8*/
            case 0x30:/*JR NC,e8*/ case 0x38:/*JR C,e8*/
            {
                sbyte offset       = unchecked((sbyte)ReadNextByte());
                ConditionCode cond = (ConditionCode)((opcode >> 3) & 0x03);

                if (CheckCond(cond))
                {
                    _state.PC = (ushort)(_state.PC + offset);
                    
                    // Timing:  (12 total cycles)
                    //  - opcode fetch: 4 cycles.
                    //  - JR N',e8:     8 cycles.
                    _state.AddClockCycles(MachineCycle * 2);
                }
                else
                {
                    // Timing:  (12 total cycles)
                    //  - opcode fetch:     4 cycles.
                    //  - JR N',e8 no pop:  4 cycles.
                    _state.AddClockCycles(MachineCycle);
                }
                
                CompleteInstruction();
                return;
            }
            
            //--- JP a16
            case 0xC3:
            {
                _state.PC = ReadNextWord(); // Jump to the next address in bitstream.
                
                // Timing:  (16 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - JP a16:       12 cycles.
                _state.AddClockCycles(MachineCycle * 3);
                CompleteInstruction();
                return;
            }

            //--- JP cc,a16
            case 0xC2:/*NZ,a16*/ case 0xCA:/*Z,a16*/
            case 0xD2:/*NC,a16*/ case 0xDA:/*C,a16*/
            {
                ushort target    = ReadNextWord();
                ConditionCode cc = (ConditionCode)((opcode >> 3) & 0x03);

                if (CheckCond(cc))
                {
                    _state.PC = target;

                    // Timing:  (16 total cycles)
                    //  - opcode fetch: 4 cycles.
                    //  - JP cc,a16:   12 cycles.
                    _state.AddClockCycles(MachineCycle * 3);
                }
                else
                {
                    // Timing:  (12 total cycles)
                    //  - opcode fetch:    4 cycles.
                    //  - JP cc,a16 miss:  8 cycles.
                    _state.AddClockCycles(MachineCycle * 2);
                }

                CompleteInstruction();
                return;
            }
            
            //--- JP HL
            case 0xE9:
            {
                _state.PC = _state.HL;  // Jump to address currently in HL
                
                // Timing:  (4 total cycles)
                //  - opcode fetch:    4 cycles.
                CompleteInstruction();
                return;
            }

            //--- RET cc
            case 0xC0:/*NZ,a16*/ case 0xC8:/*Z,a16*/
            case 0xD0:/*NC,a16*/ case 0xD8:/*C,a16*/
            {
                ConditionCode cond = (ConditionCode)((opcode >> 3) & 0x03);

                if (CheckCond(cond))
                {
                    // Condition met: pop return address into PC.
                    _state.PC = PopWord();

                    // Timing:  (20 total cycles)
                    //  - opcode fetch: 4 cycles.
                    //  - RET cc:       16 cycles
                    _state.AddClockCycles(MachineCycle * 4);
                }
                else
                {
                    // Timing:  (8 total cycles)
                    //  - opcode fetch:  4 cycles.
                    //  - RET cc no pop: 4 cycles
                    _state.AddClockCycles(MachineCycle);
                }

                CompleteInstruction();
                return;
            }

            //--- RET
            case 0xC9:
            {
                _state.PC = PopWord();
                
                // Timing:  (16 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - RET:          12 cycles
                _state.AddClockCycles(MachineCycle * 3); // total 16
                CompleteInstruction();
                return;
            }

            //--- RETI (Return from Interrupt)
            case 0xD9:
            {
                _state.PC = PopWord();      // Return from interrupt: pop return address into PC.
                _state.EnableInterrupts();  // RETI re-enables IME immediately.

                // Timing:  (16 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - RETI:         12 cycles.
                _state.AddClockCycles(MachineCycle * 3);
                
                CompleteInstruction();
                return;
            }
            
            //--- RST vec (Call to a fixed vector)
            case 0xC7: case 0xCF: case 0xD7: case 0xDF:
            case 0xE7: case 0xEF: case 0xF7: case 0xFF:
            {
                ushort vec = (ushort)(opcode & 0x38);   // Compute vector from opcode.
                
                PushWord(_state.PC);                    // Store the return address.
                _state.PC = vec;                        // Then jump to vector.
                
                // Timing:  (16 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - RST vec:      12 cycles.
                _state.AddClockCycles(MachineCycle * 3);
                CompleteInstruction();
                return;
            }
            
            //--- CALL cc,a16
            case 0xC4:/*NZ,a16*/ case 0xCC:/*Z,a16*/
            case 0xD4:/*NC,a16*/ case 0xDC:/*C,a16*/
            {
                ushort target    = ReadNextWord();
                ConditionCode cc = (ConditionCode)((opcode >> 3) & 0x03);

                if (CheckCond(cc))
                {
                    PushWord(_state.PC);    // Push return address.
                    _state.PC = target;     // Jump to target.

                    // Timing: 24 total cycles.
                    // - opcode fetch: 4 cycles.
                    // - CALL cc,a16:  20 cycles.
                    _state.AddClockCycles(MachineCycle * 5);
                }
                else
                {
                    // Condition not met: no push, no jump.
                    // Timing: 12 total cycles.
                    // - opcode fetch:       4 cycles.
                    // - CALL cc,a16 miss:   8 cycles.
                    _state.AddClockCycles(MachineCycle * 2);
                }

                CompleteInstruction();
                return;
            }

            //--- CALL a16
            case 0xCD:
            {
                ushort target = ReadNextWord();
                
                PushWord(_state.PC);    // Push return address.
                _state.PC = target;     // Jump to target.
                
                // Timing: 24 total cycles.
                // - opcode fetch: 4 cycles.
                // - CALL a16:     20 cycles.
                _state.AddClockCycles(MachineCycle * 5);
                CompleteInstruction();
                return;
            }
            
            //----------    STACK    ----------//
            //--- POP rr
            case 0xC1: case 0xD1: case 0xE1: case 0xF1:
            {
                ushort val = PopWord(); // pop 16-bit (little-endian) value from stack, SP += 2

                // Bits 5-4 encode destination pair: 00=BC, 01=DE, 10=HL, 11=AF.
                switch ((opcode >> 4) & 0x03)
                {
                    case 0x00: _state.BC = val; break;
                    case 0x01: _state.DE = val; break;
                    case 0x02: _state.HL = val; break;
                    case 0x03: _state.AF = val; break; // AF setter masks low nibble of F
                }
                
                // Timing:  (12 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - POP rr:       8 cycles
                _state.AddClockCycles(MachineCycle * 2);
                CompleteInstruction();
                return;
            }
            
            //--- PUSH rr
            case 0xC5: case 0xD5: case 0xE5: case 0xF5:
            {
                // Bits 5-4 encode source pair: 00=BC, 01=DE, 10=HL, 11=AF.
                ushort val = ((opcode >> 4) & 0x03) switch
                {
                    0x00 => _state.BC,
                    0x01 => _state.DE,
                    0x02 => _state.HL,
                    _    => _state.AF,
                };
                
                PushWord(val);  // Push 16-bit (little-endian) value onto stack, SP-=2
                
                // Timing:  (16 total cycles)
                //  - opcode fetch: 4 cycles.
                //  - PUSH rr:      12 cycles
                _state.AddClockCycles(MachineCycle * 3);
                CompleteInstruction();
                return;
            }

            //----------    MEM    ----------//
            //--- LD (BC/DE),A
            case 0x02: case 0x12:
            {
                // Select the destination address from BC/DE based on opcode.
                ushort dest = (opcode == 0x02 ? _state.BC : _state.DE);
                
                // Store accumulator into memory at the destination address.
                _bus.WriteByte(dest, _state.A);
                
                // Timing:  (8 total)
                //  - opcode fetch: 4 cycles.
                //  - LD (BC/DE),A: 4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }
            
            //--- LD A,(BC/DE)
            case 0x0A: case 0x1A:
            {
                // Select the source address from BC/DE based on opcode.
                ushort src = (opcode == 0x0A ? _state.BC : _state.DE);
                
                // Load accumulator from memory at the source address.
                _state.A = _bus.ReadByte(src);
                
                // Timing:  (8 total)
                //  - opcode fetch: 4 cycles.
                //  - LD A,(BC/DE): 4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }
            
            // --- LD (HL+/-),A
            case 0x22: case 0x32:
            {
                // Write to HL then increment or decrement based on opcode.
                WriteAtHL(_state.A, 
                    opcode == 0x22 ? HLStep.Increment : HLStep.Decrement);

                // Timing:  (8 total)
                //  - opcode fetch: 4 cycles.
                //  - LD (HL+/-),A: 4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }

            // --- LD A,(HL+/-)
            case 0x2A: case 0x3A:
            {
                // Read from HL then increment or decrement based on opcode.
                _state.A = ReadAtHL(
                    opcode == 0x2A ? HLStep.Increment : HLStep.Decrement);

                // Timing:  (8 total)
                //  - opcode fetch: 4 cycles.
                //  - LD (HL+/-),A: 4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }

            //--- LD (a16),SP
            case 0x08:
            {
                // Read the destination address from the immediate operand.
                ushort dest = ReadNextWord();

                // Store SP as little-endian at [a16] and [a16+1].
                _bus.WriteByte(dest, (byte)(_state.SP & 0x00FF));
                _bus.WriteByte((ushort)(dest + 1), (byte)(_state.SP >> 8));

                // Timing:  (20 total)
                //  - opcode fetch:  4 cycles.
                //  - LD (a16),SP:   16 cycles.
                _state.AddClockCycles(MachineCycle * 4);
                CompleteInstruction();
                return;
            }
            
            //--- LDH (a8),A | LDH A,(a8)
            case 0xE0:/*LDH (a8),A*/ case 0xF0:/*LDH A,(a8)*/
            {
                byte offset = ReadNextByte();               // Read 8-bit offset from instruction stream.
                ushort addr = (ushort)(0xFF00 + offset);    // LDH uses high-memory I/O space at 0xFF00 + a8.
                
                if (opcode == 0xE0)
                    _bus.WriteByte(addr, _state.A);         // Store accumulator into high-memory I/O/register space.
                else
                    _state.A = _bus.ReadByte(addr);         // Load accumulator from high-memory I/O/register space.
                
                // Timing:  (12 total)
                //  - opcode fetch:             4 cycles.
                //  - LDH (a8),A | LDH A,(a8):  8 cycles.
                _state.AddClockCycles(MachineCycle * 2);
                CompleteInstruction();
                return;
            }
            
            //--- LD (C),A | LD A,(C)
            case 0xE2:/*LD (C),A*/ case 0xF2:/*LD A,(C)*/
            {
                ushort addr = (ushort)(0xFF00 + _state.C);   // Uses high-memory I/O space addressed by register C.

                if (opcode == 0xE2)
                    _bus.WriteByte(addr, _state.A);          // Store accumulator into address 0xFF00 + C.
                else
                    _state.A = _bus.ReadByte(addr);          // Load accumulator from address 0xFF00 + C.

                // Timing:  (8 total)
                //  - opcode fetch:           4 cycles.
                //  - LD (C),A | LD A,(C):    4 cycles.
                _state.AddClockCycles(MachineCycle);
                CompleteInstruction();
                return;
            }
            
            //--- LD (a16),A | LD A,(a16)
            case 0xEA:/*LDH (a16),A*/ case 0xFA:/*LDH A,(a16)*/          
            {
                ushort addr = ReadNextWord();         // Read full 16-bit address from instruction stream.
                
                if (opcode == 0xEA)
                    _bus.WriteByte(addr, _state.A);   // Store accumulator at absolute address.
                else
                    _state.A = _bus.ReadByte(addr);   // Load accumulator from absolute address.

                // Timing:  (16 total)
                //  - opcode fetch:             4 cycles.
                //  - LD (a16),A | LD A,(a16): 12 cycles.
                _state.AddClockCycles(MachineCycle * 3); // total 16
                CompleteInstruction();
                return;
            }
            
            default: throw new NotSupportedException($"Opcode {opcode} not supported");
        }
    }
    
    //--------------------------------------------------------------------------------------------------//
    //                                            HELPERS                                               //
    //--------------------------------------------------------------------------------------------------//
    /// <summary>
    /// Checks for pending enabled interrupts, waking HALT if needed and servicing one if IME is enabled.
    /// Returns true when this CPU step was consumed by interrupt handling.
    /// </summary>
    private bool HandleInterrupts()
    {
        byte pending = GetPendingInterrupts();
        
        if (pending == 0)   return false;       // No pending interrupts, continue.
        if (_state.Halted)  _state.Resume();    // HALT exits once an enabled interrupt is pending.
        if (_state.Stopped) return false;       // STOP wake remains simplified for now.
        
        if (!_state.InterruptMasterEnabled)
            return false;                       // Interrupt is pending, but IME still blocks servicing.

        ServiceInterrupt(pending);
        return true;
    }
    
    /// <summary>
    /// Services the highest-priority pending interrupt, clears its IF bit, disables IME, and jumps to its vector.
    /// </summary>
    private void ServiceInterrupt(byte pendingInterrupts)
    {
        if (_bus is null) return;

        byte   interruptMask;
        ushort vector;

        if ((pendingInterrupts & InterruptVBlank) != 0)
        {
            interruptMask = InterruptVBlank;
            vector = 0x0040;
        }
        else if ((pendingInterrupts & InterruptStat) != 0)
        {
            interruptMask = InterruptStat;
            vector = 0x0048;
        }
        else if ((pendingInterrupts & InterruptTimer) != 0)
        {
            interruptMask = InterruptTimer;
            vector = 0x0050;
        }
        else if ((pendingInterrupts & InterruptSerial) != 0)
        {
            interruptMask = InterruptSerial;
            vector = 0x0058;
        }
        else
        {
            interruptMask = InterruptJoypad;
            vector = 0x0060;
        }

        byte interruptFlags = _bus.ReadByte(InterruptFlagAddress);
        _bus.WriteByte(InterruptFlagAddress, (byte)(interruptFlags & ~interruptMask)); // Acknowledge chosen interrupt.

        _state.DisableInterrupts();   // Servicing an interrupt clears IME immediately.
        PushWord(_state.PC);          // Save current PC so RETI can resume execution.
        _state.PC = vector;           // Jump to interrupt handler vector.

        // Timing: 20 total cycles.
        // - interrupt entry behaves like a call to the vector.
        _state.AddClockCycles(MachineCycle * 5);
    }
    
    /// <summary> Computes IF & IE to determine which enabled interrupts are currently pending. </summary>
    private byte GetPendingInterrupts()
    {
        if (_bus is null) return 0;

        byte interruptFlags  = _bus.ReadByte(InterruptFlagAddress);
        byte interruptEnable = _bus.ReadByte(InterruptEnableAddress);
        return (byte)(interruptFlags & interruptEnable & 0x1F);
    }
    
    /// <summary> Reads the next word from the instruction stream; advances the PC. </summary>
    private byte ReadNextByte()
    {
        if (_bus is null) return 0;

        byte value = _bus.ReadByte(_state.PC);
        _state.PC++;

        return value;
    }

    /// <summary> Reads the next word from the instruction stream; advances the PC. </summary>
    private ushort ReadNextWord()
    {
        byte lo = ReadNextByte();
        byte hi = ReadNextByte();
        
        return (ushort)((hi << 8) | lo);
    }

    /// <summary> Push a word onto the stack. </summary>
    private void PushWord(ushort value)
    {
        if (_bus is null) return;

        _state.SP--; _bus.WriteByte(_state.SP, (byte)(value >> 8));   // high byte
        _state.SP--; _bus.WriteByte(_state.SP, (byte)(value & 0xFF)); // low byte
    }

    /// <summary> Pop a word from the stack. </summary>
    private ushort PopWord()
    {
        if (_bus is null) return 0;
        
        byte lo = _bus.ReadByte(_state.SP); _state.SP++;
        byte hi = _bus.ReadByte(_state.SP); _state.SP++;
        
        return (ushort)((hi << 8) | lo);
    }

    /// <summary> How HL should be adjusted after a memory access. </summary>
    private enum HLStep { None, Increment, Decrement }

    /// <summary> Read a byte from the address in HL, optionally adjusting HL after reading. </summary>
    private byte ReadAtHL(HLStep step = HLStep.None)
    {
        if (_bus is null) return 0;

        byte value = _bus.ReadByte(_state.HL);

        if (step == HLStep.Increment) _state.HL++;
        if (step == HLStep.Decrement) _state.HL--;
        
        return value;
    }
    
    /// <summary> Write a byte to the address in HL, optionally adjusting HL after writing. </summary>
    private void WriteAtHL(byte value, HLStep step = HLStep.None)
    {
        if (_bus is null) return;

        _bus.WriteByte(_state.HL, value);

        if (step == HLStep.Increment) _state.HL++;
        if (step == HLStep.Decrement) _state.HL--;
    }
    
    /// <summary> Read an 8-bit register by LR35902 register index (B,C,D,E,H,L,(HL),A). </summary>
    private byte ReadReg8(int reg)
    {
        return reg switch
        {
            0 => _state.B,
            1 => _state.C,
            2 => _state.D,
            3 => _state.E,
            4 => _state.H,
            5 => _state.L,
            6 => ReadAtHL(),
            7 => _state.A,
            _ => throw new ArgumentOutOfRangeException(nameof(reg), reg, "register index must be 0..7")
        };
    }
    
    /// <summary> Write an 8-bit register by LR35902 register index (B,C,D,E,H,L,(HL),A). </summary>
    private void WriteReg8(int reg, byte value)
    {
        switch (reg)
        {
            case 0: _state.B = value; break;
            case 1: _state.C = value; break;
            case 2: _state.D = value; break;
            case 3: _state.E = value; break;
            case 4: _state.H = value; break;
            case 5: _state.L = value; break;
            case 6: WriteAtHL(value); break;
            case 7: _state.A = value; break;
            default:
                throw new ArgumentOutOfRangeException(nameof(reg), reg, "register index must be 0..7");
        }
    }
    
    /// <summary> Set CPU flags in Z/N/H/C order. </summary>
    private void SetFlagsZNHC(bool z, bool n, bool h, bool c)
    {
        _state.SetFlags(z, n, h, c);
    }
    
    /// <summary>
    /// Adds signed 8-bit immediate to SP and updates flags per LR35902 rules.
    /// Used by: ADD SP,e8 and LD HL,SP+e8.
    /// </summary>
    private ushort AddSignedToSP(byte e8)
    {
        ushort sp = _state.SP;
        int    signed = unchecked((sbyte)e8);
        ushort result = (ushort)(sp + signed);

        // GB rule: Z=0, N=0, H/C from low-byte addition using unsigned e8.
        bool h = ((sp & 0x0F) + (e8 & 0x0F)) > 0x0F;
        bool c = ((sp & 0xFF) + e8) > 0xFF;

        SetFlagsZNHC(z: false, n: false, h: h, c: c);
        return result;
    }
    
    /// <summary> Makes condition code usage clearer than raw ints </summary>
    private enum ConditionCode { NZ = 0, Z  = 1, NC = 2, C  = 3 }
    
    /// <summary> Evaluate NZ/Z/NC/C condition code used by JR/JP/CALL/RET conditional forms. </summary>
    private bool CheckCond(ConditionCode cond)
    {
        return cond switch
        {
            ConditionCode.NZ => !_state.FlagZ,
            ConditionCode.Z  =>  _state.FlagZ,
            ConditionCode.NC => !_state.FlagC,
            ConditionCode.C  =>  _state.FlagC,
            _ => throw new ArgumentOutOfRangeException(nameof(cond), cond, null)
        };
    }

    /// <summary> Applies any delayed EI effect after the current instruction completes, then returns. </summary>
    private void CompleteInstruction()
    {
        if (_interruptEnabledPendingStateSnapshot)
            _state.ApplyPendingInterruptEnable();
    }
}
